      "event": "T2 expires",
      "action": "Broadcast DHCPREQUEST",
      "to": "REBINDING"
    },
    {
      "from": "BOUND",
      "event": "Lease expired/DHCPNAK",
      "action": "Halt network",
      "to": "INIT-REBOOT"
    }
  ]
